def wilson(k,n):
 z=1.95996398454;v=k/n;d=1+z*z/n;centre=(v+z*z/(2*n))/d;half=z*np.sqrt(v*(1-v)/n+z*z/(4*n*n))/d
 return 100*(centre-half),100*(centre+half)

